import java.util.Map;
import javax.sql.DataSource;
public final class CheckoutDatabase {
  private final Map<String, DataSource> targets;
  private final String checkoutTarget;
  public CheckoutDatabase(Map<String, DataSource> targets, String checkoutTarget) {
    this.targets = targets;
    this.checkoutTarget = checkoutTarget;
  }
  public Connection open() throws SQLException {
    return targets.get(checkoutTarget).getConnection();
  }
}

